1	import assert from 'node:assert/strict';
2	import { applyPatch, PatchError } from '../jsonpatch.mjs';
3	
4	export function expectPatchError(fn, message, index) {
5	  assert.throws(fn, (err) => {
6	    assert.ok(err instanceof PatchError, 'instanceof PatchError');
7	    assert.ok(err instanceof Error, 'instanceof Error');
8	    assert.strictEqual(err.name, 'PatchError');
9	    assert.strictEqual(err.message, message);
10	    assert.strictEqual(err.index, index);
11	    return true;
12	  });
13	}
14	
15	export function expectOpError(doc, op, reason, index = 0) {
16	  expectPatchError(() => applyPatch(doc, [op]), `operation ${index}: ${reason}`, index);
17	}
18	
19	export function expectPatchFail(doc, patch, reason, index) {
20	  expectPatchError(() => applyPatch(doc, patch), `operation ${index}: ${reason}`, index);
21	}
22	
23	export function one(doc, op) {
24	  return applyPatch(doc, [op]);
25	}
26	
27	export function deepFreeze(value) {
28	  if (typeof value === 'object' && value !== null && !Object.isFrozen(value)) {
29	    Object.freeze(value);
30	    for (const key of Reflect.ownKeys(value)) deepFreeze(value[key]);
31	  }
32	  return value;
33	}
34	
35	export function nest(depth) {
36	  let value = [];
37	  for (let i = 1; i < depth; i++) value = [value];
38	  return value;
39	}
40	
41	export function depthOf(value) {
42	  let depth = 0;
43	  let cur = value;
44	  while (Array.isArray(cur)) {
45	    depth++;
46	    cur = cur[0];
47	  }
48	  return depth;
49	}
50	
51	export function assertNoSharedArrays(a, b) {
52	  let x = a;
53	  let y = b;
54	  while (Array.isArray(x)) {
55	    assert.notStrictEqual(x, y);
56	    x = x[0];
57	    y = y[0];
58	  }
59	}
