16	describe('applyPatch does not mutate inputs', () => {
17	  const makeDoc = () => ({ a: [1, 2, 3], b: { c: 1 }, d: 'x' });
18	  const makePatch = () => [
19	    { op: 'add', path: '/a/0', value: { n: [1] } },
20	    { op: 'remove', path: '/b/c' },
21	    { op: 'replace', path: '/d', value: [0] },
22	    { op: 'move', from: '/a/1', path: '/b/m' },
23	    { op: 'copy', from: '/a', path: '/e' },
24	  ];
25	
26	  it('on success', () => {
27	    const doc = makeDoc();
28	    const patch = makePatch();
29	    const docSnap = structuredClone(doc);
30	    const patchSnap = structuredClone(patch);
31	    applyPatch(doc, patch);
32	    assert.deepStrictEqual(doc, docSnap);
33	    assert.deepStrictEqual(patch, patchSnap);
34	  });
35	
36	  it('on failure after earlier ops succeeded', () => {
37	    const doc = makeDoc();
38	    const patch = [...makePatch(), { op: 'test', path: '/d', value: 'nope' }];
39	    const docSnap = structuredClone(doc);
40	    const patchSnap = structuredClone(patch);
41	    expectPatchFail(doc, patch, 'test failed', 5);
42	    assert.deepStrictEqual(doc, docSnap);
43	    assert.deepStrictEqual(patch, patchSnap);
44	  });
45	
46	  for (const first of [
47	    { op: 'add', path: '/q', value: 1 },
48	    { op: 'remove', path: '/d' },
