377	function waitForExit(child, ms) {
378	  return new Promise((resolve, reject) => {
379	    const timer = setTimeout(() => {
380	      child.kill('SIGKILL');
381	      reject(new Error('CLI did not exit while stdin was still open'));
382	    }, ms);
383	    let stderr = '';
384	    child.stderr.on('data', (c) => { stderr += c; });
385	    child.on('close', (code) => {
386	      clearTimeout(timer);
387	      resolve({ code, stderr });
388	    });
389	  });
390	}
